// lib/errors.ts
export class APIError extends Error {
  constructor(
    public statusCode: number,
    public code: string,
    message: string,
    public details?: unknown
  ) {
    super(message);
    this.name = "APIError";
  }
}

export class BadRequestError extends APIError {
  constructor(message: string, details?: unknown) {
    super(400, "BAD_REQUEST", message, details);
  }
}

export class NotFoundError extends APIError {
  constructor(resource: string) {
    super(404, "NOT_FOUND", `${resource} not found`);
  }
}

export class UnauthorizedError extends APIError {
  constructor() {
    super(401, "UNAUTHORIZED", "Authentication required");
  }
}

// app/posts/[id]/route.ts
import { NextResponse } from "next/server";
import { NotFoundError, APIError } from "@/lib/errors";

export async function GET(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const post = await db.post.findUnique({
      where: { id: params.id },
    });

    if (!post) {
      throw new NotFoundError("Post");
    }

    return NextResponse.json({ post });
  } catch (error) {
    if (error instanceof APIError) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: error.code,
            message: error.message,
            details: error.details,
          },
        },
        { status: error.statusCode }
      );
    }

    console.error("Unexpected error in GET /posts/[id]:", error);
    return NextResponse.json(
      { success: false, error: { code: "INTERNAL", message: "Something went wrong" } },
      { status: 500 }
    );
  }
}

// lib/api-wrapper.ts
export function withErrorHandling(
  handler: () => Promise<Response>
) {
  return async (request: Request, ...args: unknown[]) => {
    try {
      return await handler();
    } catch (error) {
      if (error instanceof APIError) {
        return NextResponse.json(
          { success: false, error: { code: error.code, message: error.message } },
          { status: error.statusCode }
        );
      }

      console.error("API error:", error);
      return NextResponse.json(
        { success: false, error: { code: "INTERNAL", message: "Something went wrong" } },
        { status: 500 }
      );
    }
  };
}

// usage
export const GET = withErrorHandling(async (request: Request) => {
  const posts = await db.post.findMany();
  return NextResponse.json({ success: true, data: posts });
});
